/**
 * PlanComment is one message on a plan node's thread. Author is "user" or
 * "agent". SessionID records which agent session the comment was delivered
 * into, so a thread read back later says which run it belonged to — it is not
 * used for routing.
 * 
 * Threads are read-only history: no resolve, reopen, edit or delete
 * (codegraph.mdx § Non-goals). A thread lives as long as its plan node: a new
 * proposal that keeps the node (same ID and FQN) keeps the thread, one that
 * drops or changes the node drops it (see SavePlan).
 */
export interface PlanComment {
    "planNodeId": string;
    "commentId": string;
    "author": string;
    "body": string;

    /**
     * unix seconds
     */
    "createdAt": number;
    "sessionId": string;
}

